const PLACES = ["ones", "tens", "hundreds", "thousands", "ten thousands", "lakhs"];
const ADDEND = CONTENT.hundred;
const ANSWER = CONTENT.one;
const CARRY = CONTENT.pointer;
const AMBER = CONTENT.ten;
const ZERO = "#767676";
const inkOf = (c) => shade(c, 0.25);
const CW = 160;
const RIGHT = 1066;
const colX = (k) => RIGHT - (k + 1) * CW;
const colC = (k) => colX(k) + CW / 2;
const CIRC = { y: 30, r: 23 };
const LANE = { y: 64, h: 12 };
const HEAD_TOP = 74;
const SUM_H = 60;
const FGAP = 6;
